-- FRESH DB ONLY. Phase 460 tests (RPT-C3 R7 part 3): #168 coupon / offer usage, #169 customer acquisition cost, #170 repeat purchase after a promotion, #171 marketing ROI.
--   bash tests/sql/rptc3_run.sh 460
-- The CRM-F coupon module is NOT in this build: T2 creates SCRATCH STAND-INS for its two tables (same column names the report reads) to prove the report reads them when they exist
-- and creates no coupon table of its own. Test data only (test_* names).
\ir ../tests/sql/rptc3_head.sql
select to_char(tt.today() - 5, 'YYYY-MM-DD') as f, to_char(tt.today() + 1, 'YYYY-MM-DD') as t \gset
select tt.as(:'u_o');

-- T1 coupon / offer usage without the coupon module
select mkt_coupon_usage(:'f'::date, :'t'::date) as cu \gset
select tt.chk('T1 CRM-F is not installed: said so, nothing validated', ((:'cu'::jsonb)->>'crmf_installed') = 'false' and (:'cu'::jsonb)->'notes' ? 'crmf_not_installed' and jsonb_array_length((:'cu'::jsonb)->'validated') = 0);
select tt.chk('T1 the typed code is listed as typed, not validated: TESTOFFER10 on 1 bill of 200', (select (x->>'offer_code') = 'TESTOFFER10' and tt.n(x,'bills') = 1 and tt.n(x,'net') = 200 from jsonb_array_elements((:'cu'::jsonb)->'typed') x limit 1) and (:'cu'::jsonb)->'notes' ? 'typed_codes_not_validated');
select tt.chk('T1 this package created no coupon table', to_regclass('public.crmf_coupons') is null and not exists (select 1 from pg_tables where schemaname = 'public' and tablename like '%coupon%'));

-- T2 with the coupon module present: it is READ, and a sale in both is counted once
create table public.crmf_coupons (id uuid primary key default gen_random_uuid(), code text unique, name text, kind text, value numeric, campaign_ref text);
create table public.crmf_coupon_uses (id bigint generated by default as identity primary key, coupon_id uuid references public.crmf_coupons(id), sale_id uuid unique references public.sales(id),
  customer_id uuid, location_id int, bill_total numeric, discount_expected numeric, discount_given numeric, mismatch boolean default false, at timestamptz default now());
insert into public.crmf_coupons (code, name, kind, value, campaign_ref) values ('TESTOFFER10', 'test coupon ten', 'percent', 10, 'test_alpha_promo'), ('TESTCPN5', 'test coupon five', 'amount', 5, null);
insert into public.crmf_coupon_uses (coupon_id, sale_id, customer_id, location_id, bill_total, discount_expected, discount_given, mismatch)
  select c.id, tt.k('s1')::uuid, null, 1, 200, 20, 0, true from public.crmf_coupons c where c.code = 'TESTOFFER10';
select mkt_coupon_usage(:'f'::date, :'t'::date) as cu2 \gset
select tt.chk('T2 CRM-F present: the coupon use is read from its tables (1 use, mismatch counted)', ((:'cu2'::jsonb)->>'crmf_installed') = 'true' and (select tt.n(x,'uses') = 1 and tt.n(x,'mismatches') = 1 and x->>'campaign_ref' = 'test_alpha_promo' from jsonb_array_elements((:'cu2'::jsonb)->'validated') x limit 1));
select tt.chk('T2 the same sale (typed AND validated) is counted once: not in the typed block', jsonb_array_length((:'cu2'::jsonb)->'typed') = 0 and tt.n((:'cu2'::jsonb)->'totals','validated_uses') = 1);
select record_sale2(gen_random_uuid(),1,format('[{"item_id":"%s","qty":1,"price":100}]',(select id from items where code='W1D-FG'))::jsonb,0,'[{"mode":"cash","amount":100}]',null,null,'retail',null,false)->>'id' as s8 \gset
select mkt_tag_sale(:'s8'::uuid, null, 'testcpn5') as tg2 \gset
select tt.chk('T2 a typed code that is a known coupon stores the coupon id next to the code', ((:'tg2'::jsonb)->>'coupon_known') = 'true' and (select coupon_id from mkt_sale_tags where sale_id = :'s8'::uuid) = (select id from public.crmf_coupons where code = 'TESTCPN5'));
select mkt_tag_sale(tt.k('s3')::uuid, null, 'NOSUCHCODE') ->> 'coupon_known' as nk \gset
select tt.chk('T2 a typed code that no coupon has is kept as typed (coupon id null)', :'nk' = 'false' and (select coupon_id from mkt_sale_tags where sale_id = tt.k('s3')::uuid) is null);
select tt.chk('T2 the typed block lists the sale whose code matched a coupon but has no recorded use', exists (select 1 from jsonb_array_elements(mkt_coupon_usage(:'f'::date, :'t'::date)->'typed') x where x->>'offer_code' = 'TESTCPN5'));

-- T3 customer acquisition cost
select mkt_cac(:'f'::date, :'t'::date) as cac \gset
select tt.chk('T3 two new customers; one has a source: coverage 50.0%', tt.n((:'cac'::jsonb)->'totals','new_customers') = 2 and tt.n((:'cac'::jsonb)->'totals','new_with_source') = 1 and tt.n((:'cac'::jsonb)->'coverage','source_pct') = 50.0);
select tt.chk('T3 all marketing spend 600 / 2 new customers = 300 (a blend, said so)', tt.n((:'cac'::jsonb)->'totals','cac_all') = 300 and (:'cac'::jsonb)->'notes' ? 'cac_all_is_a_blend');
select tt.chk('T3 by source: the source that is a campaign gets that campaign spend 300 -> CAC 300; the blank source has no CAC', (select tt.n(x,'cac') = 300 and x->>'campaign_code' = tt.k('ca') from jsonb_array_elements((:'cac'::jsonb)->'rows') x where x->>'source' = 'test_alpha_promo') and (select x->>'cac' is null from jsonb_array_elements((:'cac'::jsonb)->'rows') x where x->>'source' is null));
select tt.chk('T3 attributable CAC uses only the spend of campaigns that are a source', tt.n((:'cac'::jsonb)->'totals','attributable_spend') = 300 and tt.n((:'cac'::jsonb)->'totals','cac_attributable') = 300);
insert into customers (mobile, name, source, customer_since) values ('01800000779', 'test_customer_old', 'test_unknown_src', tt.today() - 100), ('01800000780', 'test_customer_c3d', 'test_unknown_src', tt.today());
select tt.chk('T3 a customer from before the period is not new; a source that is no campaign has no CAC', tt.n(mkt_cac(:'f'::date, :'t'::date)->'totals','new_customers') = 3 and (select x->>'cac' is null and x->>'campaign_code' is null from jsonb_array_elements(mkt_cac(:'f'::date, :'t'::date)->'rows') x where x->>'source' = 'test_unknown_src'));
select tt.chk('T3 with a place chosen only customers whose first bill was there count (1)', tt.n(mkt_cac(:'f'::date, :'t'::date, 1)->'totals','new_customers') = 1 and mkt_cac(:'f'::date, :'t'::date, 1)->'notes' ? 'place_filter_uses_first_sale_place');
select tt.chk('T3 nobody new in a quiet period: no CAC (null), not 0', mkt_cac(tt.today()-400, tt.today()-399)->'totals'->>'cac_all' is null);

-- T4 repeat purchase after a promotion
select tt.chk('T4 no window typed and no setting: "data needed", nothing assumed', (mkt_repeat_after_promo(null, null))->'data_needed' ? 'mkt_repeat_days');
select tt.err('T4 a window of 0 days is refused', $$select mkt_repeat_after_promo(null, 0)$$, 'bad_days');
select tt.err('T4 a window over a year is refused', $$select mkt_repeat_after_promo(null, 400)$$, 'bad_days');
select mkt_campaign_save(null, jsonb_build_object('name_bn','test_past_promo','force',true,'start',tt.today()-20,'end',tt.today()-5)) ->> 'value_code' as pp \gset
insert into customers (mobile, name) values ('01800000781', 'test_customer_x'), ('01800000782', 'test_customer_y');
select record_sale2(gen_random_uuid(),1,format('[{"item_id":"%s","qty":1,"price":100}]',(select id from items where code='W1D-FG'))::jsonb,0,'[{"mode":"cash","amount":100}]','01800000781','test_customer_x','retail',null,false)->>'id' as xa \gset
select record_sale2(gen_random_uuid(),1,format('[{"item_id":"%s","qty":1,"price":100}]',(select id from items where code='W1D-FG'))::jsonb,0,'[{"mode":"cash","amount":100}]','01800000782','test_customer_y','retail',null,false)->>'id' as ya \gset
select record_sale2(gen_random_uuid(),1,format('[{"item_id":"%s","qty":1,"price":100}]',(select id from items where code='W1D-FG'))::jsonb,0,'[{"mode":"cash","amount":100}]','01800000781','test_customer_x','retail',null,false)->>'id' as xb \gset
select mkt_tag_sale(:'xa'::uuid, :'pp', null) ->> 'ok' as t1 \gset
select mkt_tag_sale(:'ya'::uuid, :'pp', null) ->> 'ok' as t2 \gset
-- move the three bills back in time (the first two inside the promotion, the repeat 2 days ago)
select set_config('session_replication_role', 'replica', false);
update sales set sale_date = tt.today() - 10 where id in (:'xa'::uuid, :'ya'::uuid);
update sales set sale_date = tt.today() - 2 where id = :'xb'::uuid;
select set_config('session_replication_role', 'origin', false);
select mkt_repeat_after_promo(:'pp', 3) as rp \gset
select tt.chk('T4 2 promotion customers, 1 bought again within 3 days after the end: 50.0%, window complete', (select tt.n(x,'promo_customers') = 2 and tt.n(x,'repeat_customers') = 1 and tt.n(x,'repeat_pct') = 50.0 and (x->>'window_complete') = 'true' and (x->>'window_to')::date = tt.today() - 2 from jsonb_array_elements((:'rp'::jsonb)->'rows') x limit 1));
select tt.chk('T4 identified share is shown (both tagged bills have a customer)', (select tt.n(x,'identified_pct') = 100 from jsonb_array_elements((:'rp'::jsonb)->'rows') x limit 1));
select tt.chk('T4 a 1-day window misses the repeat (2 days after the end... the window ends 4 days ago): 0 repeaters', (select tt.n(x,'repeat_customers') = 0 from jsonb_array_elements(mkt_repeat_after_promo(:'pp', 1)->'rows') x limit 1));
select tt.chk('T4 a window that is not over yet gives no percentage, only "so far"', (select x->>'repeat_pct' is null and (x->>'window_complete') = 'false' and x->>'repeat_pct_so_far' is not null from jsonb_array_elements(mkt_repeat_after_promo(:'pp', 30)->'rows') x limit 1));
select set_rule('mkt_repeat_days', '3') is null as sr \gset
select tt.chk('T4 the setting supplies the window when none is typed', mkt_repeat_after_promo(:'pp', null)->>'window_days' = '3');
select set_rule('mkt_repeat_days', null) is null as sr2 \gset
select mkt_campaign_save(null, '{"name_bn":"test_silent_c","force":true}') ->> 'value_code' as sc \gset
select tt.chk('T4 a campaign with no tagged bill has no row', jsonb_array_length(mkt_repeat_after_promo(:'sc', 3)->'rows') = 0);

-- T5 ROI (attributable data only)
select mkt_roi(:'f'::date, :'t'::date) as roi \gset
select tt.chk('T5 campaign A: (258 - 300) / 300 = -14.0%, revenue per taka 1.00', (select tt.n(x,'roi_pct_costed_part') = -14.0 and tt.n(x,'revenue_per_taka') = 1.00 and x->>'why_no_roi' is null from jsonb_array_elements((:'roi'::jsonb)->'rows') x where x->>'campaign_code' = tt.k('ca')));
select tt.chk('T5 campaign B: (152 - 200) / 200 = -24.0%', (select tt.n(x,'roi_pct_costed_part') = -24.0 from jsonb_array_elements((:'roi'::jsonb)->'rows') x where x->>'campaign_code' = tt.k('cb')));
select tt.chk('T5 unassigned spend (100) is shown apart and is in no ROI', tt.n((:'roi'::jsonb),'unassigned_spend_not_in_roi') = 100 and (:'roi'::jsonb)->'notes' ? 'unassigned_spend_not_in_roi');
select mkt_campaign_save(null, '{"name_bn":"test_quiet_c","force":true}') ->> 'value_code' as qc \gset
select save_entry(null,'18-1',1,tt.today(), jsonb_build_object('lines', jsonb_build_array(jsonb_build_object('date',tt.today()::text,'head','2','campaign_id',:'qc','amt','70','source','bank'))), '[]') ->> 'id' as q1 \gset
select submit_entry(:'q1'::uuid) is not null as q1s \gset
select tt.chk('T5 spend with no tagged sale: no ROI, reason said (no_tagged_sales)', (select x->>'roi_pct_costed_part' is null and x->>'why_no_roi' = 'no_tagged_sales' from jsonb_array_elements(mkt_roi(:'f'::date, :'t'::date)->'rows') x where x->>'campaign_code' = :'qc'));
select tt.chk('T5 a campaign with sales but no spend line: no ROI (no_spend_recorded), revenue still shown', (select x->>'roi_pct_costed_part' is null and x->>'why_no_roi' = 'no_spend_recorded' and tt.n(x,'revenue_net') = 200 from jsonb_array_elements(mkt_roi(tt.today()-30, :'t'::date)->'rows') x where x->>'campaign_code' = :'pp'));
select tt.as(:'u_rm');
select tt.chk('T5 a reader without the cost right: ROI is null, the reason is cost_hidden, revenue per taka stays', (select x->>'roi_pct_costed_part' is null and x->>'why_no_roi' = 'cost_hidden' and tt.n(x,'revenue_per_taka') = 1.00 from jsonb_array_elements(mkt_roi(:'f'::date, :'t'::date)->'rows') x where x->>'campaign_code' = tt.k('ca')));
select tt.as(:'u_nb');
select tt.err('T6 nobody: coupons', format($$select mkt_coupon_usage('%s','%s')$$, :'f', :'t'), 'not allowed');
select tt.err('T6 nobody: CAC', format($$select mkt_cac('%s','%s')$$, :'f', :'t'), 'not allowed');
select tt.err('T6 nobody: repeat', $$select mkt_repeat_after_promo(null, 3)$$, 'not allowed');
select tt.err('T6 nobody: ROI', format($$select mkt_roi('%s','%s')$$, :'f', :'t'), 'not allowed');
select tt.as(:'u_o');
\i supabase/phase460.sql
select tt.chk('T7 paste twice keeps the setting default blank', rule_num('mkt_repeat_days') is null);
select tt.chk('T7 no journal entry is unbalanced, nothing written to the books', tt.unbalanced() = 0 and (select count(*) from journal_entries where source_type like 'mkt%') = 0);
\echo == RESULT
select 'RESULT ' || count(*) filter (where ok) || ' pass, ' || count(*) filter (where not ok) || ' fail' from tt.res;
select name from tt.res where not ok;
